\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{booktabs}

\title{Irrigation Scheduling for Greenhouse Tomatoes:\newline A Two-Season Trial at the Sutton Bonington Glasshouse}
\author{C.~Ferro, A.~Diallo, and J.~Petrov}
\date{October 2025}

\begin{document}
\maketitle

\input{sections/setup}
\input{sections/results}

\end{document}

\section{Results}

\begin{table}[ht]
\centering
\caption{Seasonal water use and marketable yield by treatment, mean per plant over the two seasons.}
\begin{tabular}{lrr}
\toprule
Treatment & Water use (L per plant) & Yield (kg per plant) \\
\midrule
Control & 92.4 & 4.1 \\
Deficit & 61.7 & 3.3 \\
Scheduled & 74.8 & 4.6 \\
\bottomrule
\end{tabular}
\label{tab:water}
\end{table}

\begin{table}[ht]
\centering
\caption{Fruit quality by treatment, mean over the two seasons.}
\begin{tabular}{lrr}
\toprule
Treatment & Brix (degrees) & Cracked fruit (\%) \\
\midrule
Control & 4.8 & 11.3 \\
Deficit & 5.9 & 6.2 \\
Scheduled & 5.4 & 7.9 \\
\bottomrule
\end{tabular}
\label{tab:quality}
\end{table}

\begin{figure}[ht]
\centering
\rule{0.6\textwidth}{5cm}
\caption{Midday substrate moisture in the Scheduled treatment over the second season; the dashed line marks the 28~\% irrigation threshold and the arrow marks the heatwave of 14 July.}
\label{fig:moisture}
\end{figure}
